def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid divider.
    divider = None
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            divider = ("col", c)
            break
    if divider is None:
        for r in range(h):
            if all(v == grid[r][0] for v in grid[r]):
                divider = ("row", r)
                break

    if divider[0] == "col":
        c = divider[1]
        left = [row[:c] for row in grid]
        right = [row[c + 1:] for row in grid]
        n = min(len(left[0]), len(right[0]))
        a = [row[-n:] for row in left]
        b = [row[:n] for row in right]
    else:
        r = divider[1]
        top, bottom = grid[:r], grid[r + 1:]
        n = min(len(top), len(bottom))
        a, b = top[-n:], bottom[:n]

    def mode(panel):
        counts = {}
        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    bg_a, bg_b = mode(a), mode(b)

    if bg_a == bg_b:
        # Mark the union of the non-background cells.
        return [
            [bg_a if x != bg_a or y != bg_b else 3
             for x, y in zip(ra, rb)]
            for ra, rb in zip(a, b)
        ]

    shared = ({v for row in a for v in row} &
              {v for row in b for v in row})
    fill = max(shared, key=lambda v:
               sum(x == v for row in a for x in row) +
               sum(x == v for row in b for x in row))

    return [
        [3 if x == fill and y == fill else fill
         for x, y in zip(ra, rb)]
        for ra, rb in zip(a, b)
    ]
